// Go
ctx, cancel := context.WithTimeout(r.Context(), 800*time.Millisecond)
defer cancel()
res, err := client.GetUser(ctx, req) // ctx mang deadline xuống tầng dưới

if dl, ok := ctx.Deadline(); ok && time.Until(dl) < 50*time.Millisecond {
    return errDeadlineTooClose // không retry nữa
}
